import client from "../client";
const retailerInvoicesAction = (data) => {
    return client.post("/retailers/invoices", data);

};

const retailerOrdersStaffAction = (data) => {
  return client.post("/retailers/orders/staff", data);
};

const retailPrescriptionsAction = (data) => {
  return client.post("/retailers/prescriptions", data);
};

export default {
  retailerInvoicesAction,
  retailerOrdersStaffAction,
  retailPrescriptionsAction
};